function privatePhoneAccountAvailable(){return typeof window!=='undefined'&&window.__SMALL_PHONE_PRIVATE__===true&&window.SmallPhoneNative&&typeof window.SmallPhoneNative.request==='function';}
/* 原生请求必须有界：一次不回应就会让「正在备份」的忙碌标志永远挂着，之后每次点立即备份都被静默拦掉。 */
function privatePhoneAccountCall(action,payload,timeoutMs){if(!privatePhoneAccountAvailable())return Promise.reject(new Error('手机号账号只在私人小手机 App 内使用'));const wait=Math.max(5000,+timeoutMs||120000);return new Promise((resolve,reject)=>{let settled=false;const done=fn=>v=>{if(settled)return;settled=true;clearTimeout(timer);fn(v);},timer=setTimeout(()=>{if(settled)return;settled=true;const e=new Error('本机「'+action+'」超过 '+Math.round(wait/1000)+' 秒没有回应，本次已中断，可以重试');e.code='NATIVE_TIMEOUT';reject(e);},wait);try{window.SmallPhoneNative.request(action,payload||{}).then(done(resolve),done(reject));}catch(e){done(reject)(e);}});}
