function privatePhoneBackupChunkEnd(text,start,size){let end=Math.min(text.length,start+Math.max(1024,+size||49152));if(end<text.length){const code=text.charCodeAt(end-1);if(code>=0xD800&&code<=0xDBFF)end--;}return Math.max(start+1,end);}
