async function privatePhoneCloudRestoreOpen(){toast('正在读取云备份…');try{const r=await privatePhoneAccountCall('account.backup.restore');if(!r||r.ok!==true)throw new Error(r&&r.message||'云备份读取失败');if(!r.found){toast('这个手机号还没有云备份');return;}const b=r.backup||{},d=b.payload;if(!d||!d.settings)throw new Error('云备份内容不完整');window._privatePhoneRestoreCandidate=d;openModal(`<h3>从手机号恢复</h3><div class="hint" style="line-height:1.8">云备份时间：<b>${esc(privatePhoneAccountDate(b.captured_at))}</b><br>大小：${esc(privatePhoneAccountBytes(b.byte_count))}<br><br>确认后会用手机号私人备份恢复。应用前会先保存当前本机完整快照，可通过“撤回上次恢复”回到恢复前；当前本机不会在确认前发生任何变化。</div><div class="btns"><button class="btn g" onclick="closeModal()">取消</button><button class="btn p" onclick="privatePhoneCloudRestoreConfirm()">确认恢复</button></div>`);}catch(e){toast((e&&e.message)||'云备份读取失败');}}
async function privatePhoneCloudRestoreConfirm(){const d=window._privatePhoneRestoreCandidate;if(!d||!d.settings)return;closeModal();toast('正在保存恢复前快照…');let before=null;try{before=await fullBackupState();await imgPut(PRIVATE_PHONE_RESTORE_ROLLBACK_KEY,{ver:1,savedAt:Date.now(),json:JSON.stringify(before)});toast('正在恢复手机号私人备份…');S=mergeStateData(d);normalizeLoadedState();phoneFriendState();if(!await saveNowAsync())throw new Error('恢复后写入本机失败');window._privatePhoneRestoreCandidate=null;stack=[];home();setTimeout(()=>toast('手机号云备份已恢复；需要时可撤回到恢复前'),120);}catch(e){if(before){try{S=mergeStateData(before);normalizeLoadedState();phoneFriendState();await saveNowAsync();render();}catch(_){}}toast((e&&e.message)||'恢复失败，已保留恢复前本机快照');}}
async function privatePhoneCloudRestoreRollback(){let rec;try{rec=await imgGet(PRIVATE_PHONE_RESTORE_ROLLBACK_KEY);}catch(_){}if(!rec||!rec.json){toast('还没有可撤回的私人恢复快照');return;}if(!await uiConfirm('撤回到上次手机号云恢复之前的本机数据？'))return;try{const d=JSON.parse(rec.json);if(!d||!d.settings)throw new Error('恢复前快照不完整');S=mergeStateData(d);normalizeLoadedState();phoneFriendState();if(!await saveNowAsync())throw new Error('撤回后写入本机失败');closeModal();stack=[];home();setTimeout(()=>toast('已撤回到手机号云恢复前'),120);}catch(e){toast('撤回失败：'+String(e&&e.message||e));}}
